[
  {
    "layers": [{"material": "graphite", "thickness_mm": 2}],
    "rationale": "Most aggressive bet. Prior data shows graphite's FE hotspot is identical (325 K) at 10, 20 and 30 mm, i.e. flat across the whole tested range -- the plate is already in the thick/semi-infinite spreading regime there, so thickness above some low critical value (tied to the size of the hotspot footprint, evidently small) buys nothing thermally. If that plateau extends down to 2 mm, hotspot stays near 325 K, comfortably under the 340 K limit, screen stays far under 420 K, and areal mass is only 3.6 kg/m^2 -- 5x lighter than the prior's best passing design (10 mm graphite at 18 kg/m^2) and 25x under the 100 kg/m^2 cap. Risk: if 2 mm is thin enough to leave the plateau, spreading resistance could rise and breach R2; this is the highest-risk, highest-reward candidate in the set."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 3}],
    "rationale": "Same plateau logic as the 2 mm graphite candidate but with more margin against leaving the thick-plate regime. Areal mass 5.4 kg/m^2, well under the prior's lightest passing design (18 kg/m^2 at 10 mm graphite). Screen and mass requirements are trivially satisfied given the huge headroom seen at 10-30 mm; thickness (3 mm) is far under the 40 mm cap. Main uncertainty is whether hotspot still tracks the flat ~325 K seen at 10 mm+."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 4}],
    "rationale": "Moderate thinning step, mass 7.2 kg/m^2, less than half the prior's 10 mm graphite record. Chosen as an intermediate point between the aggressive 2-3 mm bets and the proven 10 mm design, so that if the plateau only extends part-way down, this gauge has a better chance of still landing under 340 K while still beating the prior record on mass."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 5}],
    "rationale": "Half the prior's 10 mm graphite thickness, mass 9.0 kg/m^2 (half of 18 kg/m^2). A conservative step down from the proven point that should still be well within any reasonable estimate of the thick-plate spreading regime, while giving a real mass improvement over the prior record."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 6}],
    "rationale": "Modest thinning from the proven 10 mm graphite point (mass 10.8 kg/m^2 vs the prior's 18 kg/m^2). Chosen as a low-risk mass reduction, close enough to the tested 10-30 mm flat-hotspot band that the 325 K behaviour is expected to hold essentially unchanged, comfortably meeting the 340 K limit."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 8}],
    "rationale": "Very low-risk thinning step just below the smallest thickness Core actually scored for graphite (10 mm). Mass 14.4 kg/m^2, a real but modest improvement over the prior's 18 kg/m^2 record, with hotspot expected to remain at essentially the same ~325 K seen at 10-30 mm."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 10}],
    "rationale": "Exact match to the prior's Core-scored 10 mm graphite design (325 K hotspot, 402 K screen, 18 kg/m^2, 10 mm thickness, all PASS). Included as a known-good safety anchor: if every thinner graphite bet in this set turns out to fall outside the plateau and fail R2, this candidate is expected to still meet all four requirements at the prior's already-good mass."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 3}],
    "rationale": "Aggressive thinning on the second material family as a hedge against graphite-specific risk. Aluminium's prior hotspot (324 K) was flat across 10-30 mm just like graphite's, and aluminium has a slightly higher conductivity (200 vs 150 W/mK), which should make its spreading resistance less sensitive to leaving the thick-plate regime than graphite's. Mass is 8.1 kg/m^2 -- still far below the prior's lightest passing design (18 kg/m^2) despite aluminium's higher density, because the thickness cut is large."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 4}],
    "rationale": "Moderate aluminium thinning step, mass 10.8 kg/m^2, well under the prior's 10 mm graphite record of 18 kg/m^2. Serves as a mid-risk hedge alongside the graphite bets, leveraging aluminium's higher conductivity for extra hotspot margin if thin-plate effects begin to appear."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 6}],
    "rationale": "Conservative aluminium thinning from the proven 10 mm point (mass 16.2 kg/m^2 vs prior's 27 kg/m^2 for 10 mm aluminium). Expected to sit solidly inside the same flat-hotspot band (~324 K) observed from 10-30 mm."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 10}],
    "rationale": "Exact match to the prior's Core-scored 10 mm aluminium design (324 K hotspot, 402 K screen, 27 kg/m^2, 10 mm thickness, all PASS). Second known-good safety anchor, using a different material than the graphite anchor in case there is any material-specific failure mode at thin gauges that this experiment does not anticipate."
  },
  {
    "layers": [{"material": "copper", "thickness_mm": 5}],
    "rationale": "High-conductivity fallback. Copper's prior hotspot (322 K) was the best margin of the three pure materials and, like the others, was flat across 10-30 mm, and copper's much higher conductivity (400 W/mK) should make it the most resistant of all tested materials to any rise in spreading resistance if thickness drops below the plateau's true critical value. At 5 mm, mass is 44.8 kg/m^2 -- half of the prior's 10 mm copper mass (89.6 kg/m^2) and still comfortably under the 100 kg/m^2 cap -- giving a genuine mass improvement over any copper design in the prior constellation while retaining the largest thermal safety margin in this submission as insurance against the lighter graphite/aluminium bets underperforming."
  }
]

